use std::io::{Read,Write};use spore_core::{cell_fresh_sweep_registration_v1::{Endpoint,Slot},cell_sweep_remove_v1::{self as removal,Storage}};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=80{return Err("expected four 20-byte cases".into())}let mut out=Vec::new();for row in input.chunks_exact(20){let u16at=|p:usize|u16::from_le_bytes(row[p..p+2].try_into().unwrap());let u32at=|p:usize|u32::from_le_bytes(row[p..p+4].try_into().unwrap());let head=u32at(16);let links=std::array::from_fn(|i|u16at(i*2));let slots=vec![Slot{actor:0x12345678,tag:0x87654321,endpoint_links:links},Slot{actor:if head==1{u32::MAX}else{0x55667788},tag:if head==1{u32::MAX}else{0x11223344},endpoint_links:[0xbbcc,0x99aa,0xff00,0xddee]}];let arr=|bank:usize|(0..4).map(|i|Endpoint{opening:i as u16,slot:(0x1100+bank) as u16,value_bits:0x3f000000+bank as u32*0x10000+i as u32}).collect::<Vec<_>>();let mut state=Storage{slots,old:[arr(0),arr(1)],pending:[arr(2),arr(3)],live:u32at(8),high:u32at(12),free_head:head};removal::remove(&mut state,0).map_err(|e|format!("{e:?}"))?;for x in [state.live,state.high,state.free_head]{out.extend(x.to_le_bytes())}for s in state.slots{out.extend(s.actor.to_le_bytes());out.extend(s.tag.to_le_bytes());for v in s.endpoint_links{out.extend(v.to_le_bytes())}}for array in state.old.into_iter().chain(state.pending){for e in array{out.extend(e.opening.to_le_bytes());out.extend(e.slot.to_le_bytes());out.extend(e.value_bits.to_le_bytes())}}}std::io::stdout().write_all(&out)?;Ok(())}
